const teamSetupTeams = () => [
  ...new Set([
    "",
    ...readSections(),
    ...store.bots.map((bot) => sectionKey(bot.section)),
    ...store.groups.map((group) => sectionKey(group.section)),
  ]),
];
const teamSetupRequests = new TeamSetupRequestService({
  store,
  teams: teamSetupTeams,
  canAccessTeam,
  canPersist: proposalPersistence,
  maxBots: MAX_WORKSPACE_BOTS,
  autoApply: fullAccessForSource,
  validateChange: (before, fields) =>
    assertTeamComputerChangeIdle(before, { ...before, ...fields }),
  ownsThread: (botId, threadId) => Boolean(connectorThread(botId, threadId)),
  targetBusy: (botId, sourceThreadId) => {
    if (!sourceThreadId)
      return Boolean(
        store.bot(botId)?.busy ||
          hasDirectDispatch(botId) ||
          activeGroupTurnForBot(botId) ||
          routines?.activeRunForBot(botId)
      );
    const group = activeGroupTurnForBot(botId);
    const run = routines?.activeRunForBot(botId);
    return (
      store
        .tasks(botId)
        .some(
          (task) =>
            task.threadId !== sourceThreadId && threadBusy(botId, task.threadId)
        ) ||
      [...directTurnDispatchClaims].some(
        ([threadId, claim]) =>
          threadId !== sourceThreadId && claim.botId === botId
      ) ||
      Boolean(group && group.threadId !== sourceThreadId) ||
      Boolean(run && run.threadId !== sourceThreadId)
    );
  },
  validateModel: validateModelProposal,
  // Engine-switch capability warnings come from the live registry, so a
  // card built while an instance was down never guesses.
  driverCapabilities: driverCapabilitiesFor,
  deleteBot: async (botId, revalidate, request) => {
    const result = await deleteBotWithLifecycle(botId, revalidate, request);
    if (result.status >= 400)
      throw new TeamSetupError(
        result.body.error ?? "The bot could not be deleted",
        result.status
      );
  },
});

async function resolveAndSendTeamSetup(
  res: ServerResponse,
  args: {
    botId: string;
    threadId: string;
    requestId: string;
    behavior: string;
  },
  ownerReview: boolean
): Promise<boolean> {
  const card = store
    .messagesFor(args.threadId)
    .find(
      (item) =>
        item.card?.requestId === args.requestId && item.card.teamSetupRequest
    )?.card;
  if (!card) return false;
  if (args.behavior === "allow" && !ownerReview) {
    json(res, 403, {
      error:
        "Approve team setup or deletion from the desktop app or a paired Full-access device. In a local browser, wait until every bot is idle.",
    });
    return true;
  }
  if (
    args.behavior === "allow" &&
    !card.answered &&
    !card.dismissed &&
    !card.expired
  ) {
    // Confirmed Chief setup can move bots without the ordinary PATCH route.
    // Keep that atomic Store operation behind the same shared-machine fence.
    for (const operation of card.teamSetupRequest!.operations) {
      const before = store.bot(operation.botId);
      if (before && operation.action === "update")
        assertTeamComputerChangeIdle(before, {
          ...before,
          ...operation.fields,
        });
    }
  }
  const resolved = await teamSetupRequests.resolve(args);
  if (!resolved) return false;
  if (!resolved.duplicate) {
    appendDecision(DATA_DIR, {
      threadId: args.threadId,
      requestId: args.requestId,
      botId: args.botId,
      tool: card.tool,
      summary: card.subtitle,
      decision:
        resolved.result.state === "applied" ? "user-approved" : "user-denied",
      source: "user",
    });
  }
  // The decision is recorded; the node parked on the card (a bot's own
  // conversation or a room member's) runs again with it. The card says
  // `resumed` only once the runtime took the answer, so a decision after a
  // Stop starts nothing.
  const current = store
    .messagesFor(args.threadId)
    .find((item) => item.id === resolved.messageId);
  if (
    current?.card?.teamSetupRequest?.result &&
    !current.card.teamSetupRequest.resumed
  ) {
    if (
      answerCardNode(
        args.threadId,
        current.id,
        teamSetupDecisionText(resolved.request)
      )
    ) {
      store.patchMessage(args.threadId, current.id, {
        card: {
          ...current.card,
          teamSetupRequest: { ...current.card.teamSetupRequest, resumed: true },
        },
      });
    }
  }
  json(res, 200, {
    ok: true,
    outcome: resolved.result.state === "applied" ? "allowed-once" : "rejected",
    result: resolved.result,
    alreadySettled: resolved.duplicate,
  });
  return true;
}
const ROUTINE_WEEKDAY_NAMES = [
  "sunday",
  "monday",
  "tuesday",
  "wednesday",
  "thursday",
  "friday",
  "saturday",
] as const;
const routineTimeZone = () =>
  Intl.DateTimeFormat().resolvedOptions().timeZone || "UTC";
const routineTimestamp = (value: number | undefined) =>
  value !== undefined && Number.isFinite(value)
    ? new Date(value).toISOString()
    : null;
const agentRoutine = (
  routine: ReturnType<RoutineManager["listRoutines"]>[number],
  latestRun?: RoutineRun
) => {
  // Routines created in the calendar predate chat-card redaction and may
  // contain a credential in their instructions. The list result is handed
  // back to the model, so scrub the complete value before taking its preview.
  const safeInstructions = redactSecretsInText(routine.prompt);
  const safeName = redactSecretsInText(routine.name);
  return {
    id: routine.id,
    name: safeName,
    instructions: safeInstructions.slice(0, 2_000),
    instructionsTruncated: safeInstructions.length > 2_000,
    continuity: routine.continuity === true,
    overlap: routine.overlap ?? "skip",
    runOnStartup: routine.runOnStartup === true,
    skippedRuns: routine.skippedRuns ?? 0,
    lastSkippedAt: routineTimestamp(routine.lastSkippedAt),
    failureStreak: routine.failureStreak ?? 0,
    enabled: routine.enabled,
    runOn: routine.runOn,
    durationMinutes: routine.durationMinutes,
    ...(routine.timeoutMinutes === undefined
      ? {}
      : { timeoutMinutes: routine.timeoutMinutes }),
    schedule:
      routine.schedule.type === "once"
        ? {
            type: "once" as const,
            at: new Date(routine.schedule.at).toISOString(),
          }
        : routine.schedule.type === "interval"
        ? {
            type: "interval" as const,
            everyMinutes: routine.schedule.everyMinutes,
            anchorAt: new Date(routine.schedule.anchorAt).toISOString(),
            ...(routine.schedule.weekdays === undefined
              ? {}
              : {
                  weekdays: routine.schedule.weekdays.map(
                    (day) => ROUTINE_WEEKDAY_NAMES[day]
                  ),
                }),
            ...(routine.schedule.window === undefined
              ? {}
              : { window: { ...routine.schedule.window } }),
            ...(routine.schedule.endsAt === undefined
              ? {}
              : { endsAt: new Date(routine.schedule.endsAt).toISOString() }),
          }
        : routine.schedule.type === "cron"
        ? { ...routine.schedule }
        : {
            type: "weekly" as const,
            time: routine.schedule.time,
            weekdays: routine.schedule.weekdays.map(
              (day) => ROUTINE_WEEKDAY_NAMES[day]
            ),
          },
    nextRunAt:
      routine.nextRunAt === null
        ? null
        : new Date(routine.nextRunAt).toISOString(),
    latestRun: latestRun
      ? {
          id: latestRun.id,
          status: latestRun.status,
          triggerSource:
            latestRun.triggerSource ??
            (latestRun.manual ? "manual" : "schedule"),
          scheduledFor: routineTimestamp(latestRun.scheduledFor),
          startedAt: routineTimestamp(latestRun.startedAt),
          finishedAt: routineTimestamp(latestRun.finishedAt),
          attention: latestRun.attention
            ? redactSecretsInText(latestRun.attention).slice(0, 500)
            : null,
          output: latestRun.output
            ? redactSecretsInText(latestRun.output).slice(0, 1_000)
            : null,
          error: latestRun.error
            ? redactSecretsInText(latestRun.error).slice(0, 500)
            : null,
          executionThreadId: latestRun.threadId ?? null,
        }
      : null,
  };
};
function sendRoutineResolution(
  res: ServerResponse,
  result: ReturnType<RoutineRequestService["resolve"]>
): boolean {
  if (!result.claimed) return false;
  if (result.state === "invalid") {
    json(res, result.status, { error: result.error });
    return true;
  }
  if (result.state === "already_settled") {
    json(res, 200, {
      ok: true,
      outcome:
        result.behavior === "allow"
          ? "allowed-once"
          : result.behavior === "deny"
          ? "rejected"
          : "unavailable",
      alreadySettled: true,
    });
    return true;
  }
  if (result.state === "denied") {
    json(res, 200, { ok: true, outcome: "rejected" });
    return true;
  }
  json(res, 200, {
    ok: true,
    outcome: "allowed-once",
    routineAction: result.action,
    resultId: result.resultId,
  });
  return true;
}
function resolveAndSendRoutine(
  res: ServerResponse,
  args: {
    botId: string;
    botName?: string;
    threadId: string;
    requestId: string;
    behavior: string;
  },
  ownersAnswer = false
): boolean {
  const card = store
    .messagesFor(args.threadId)
    .find(
      (message) =>
        message.card?.requestId === args.requestId &&
        message.card.routineRequest
    )?.card;
  // On a Cloud home a routine the owner approved on its card is theirs; one
  // it only changed stays whosever it was (cloudOwnerApplied).
  const operation = card?.routineRequest?.operation;
  const wasOwners =
    operation && operation.action !== "create"
      ? cloudRoutineIsOwners(operation.routineId)
      : false;
  const result = routineRequests.resolve(args);
  if (ownersAnswer && result.claimed && result.state === "applied")
    cloudOwnerApplied(result.action, result.resultId, wasOwners);
  if (
    result.claimed &&
    (result.state === "applied" || result.state === "denied")
  ) {
    appendDecision(DATA_DIR, {
      threadId: args.threadId,
      requestId: args.requestId,
      botId: args.botId,
      botName: args.botName,
      tool: card?.tool,
      summary: card?.subtitle,
      decision: result.state === "applied" ? "user-approved" : "user-denied",
      source: "user",
    });
  }
  return sendRoutineResolution(res, result);
}
