          const chip: Omit<Message, "id" | "at"> = {
            role: "bot",
            kind: "activity",
            tool: { name: `Opened thread #${task.title}`, ok: true },
            threadRef: {
              botId: from.id,
              threadId: task.threadId,
              title: task.title,
            },
          };
